import{_ as o}from"./chunks/library-overview.Bu864uIA.js";import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"画像の前処理と名前変更","description":"KomaYomi は指定したフォルダの画像をその場で読み込みます。コピーも変換もしません。改名や分割は、前処理ダイアログで明示的に操作したときだけ行います。だからこそ、巻を追加する前の数分の整理が、コマ検出・ページの対応づけ・比較リーディングの出来を決めます。少し面倒でも…","frontmatter":{"description":"KomaYomi は指定したフォルダの画像をその場で読み込みます。コピーも変換もしません。改名や分割は、前処理ダイアログで明示的に操作したときだけ行います。だからこそ、巻を追加する前の数分の整理が、コマ検出・ページの対応づけ・比較リーディングの出来を決めます。少し面倒でも…"},"headers":[],"relativePath":"ja/guide/preprocess.md","filePath":"ja/guide/preprocess.md","lastUpdated":1794803157000}'),i={name:"ja/guide/preprocess.md"};function s(l,t,n,g,c,h){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="画像の前処理と名前変更" tabindex="-1">画像の前処理と名前変更 <a class="header-anchor" href="#画像の前処理と名前変更" aria-label="Permalink to &quot;画像の前処理と名前変更&quot;">​</a></h1><p>KomaYomi は指定したフォルダの画像をその場で読み込みます。コピーも変換もしません。改名や分割は、前処理ダイアログで明示的に操作したときだけ行います。だからこそ、巻を追加する前の数分の整理が、コマ検出・ページの対応づけ・比較リーディングの出来を決めます。少し面倒でも、同じページを3言語で3回直すよりは安上がりです。</p><h2 id="この工程で解決すること" tabindex="-1">この工程で解決すること <a class="header-anchor" href="#この工程で解決すること" aria-label="Permalink to &quot;この工程で解決すること&quot;">​</a></h2><p>自動分割はきれいなスキャン向けに調整されています。ページが傾いている、スキャナの黒枠が残っている、WebP が混ざっている、あるいはどれか一つの言語でページが 1 枚足りない—そうした状態でもライブラリは開けますが、対応づけ、位置合わせ、ノート、エクスポートという後工程すべてがその問題を引き継ぎます。一度整理しておけば、同じページを 3 言語で 3 回直す手間がなくなります。</p><h2 id="ファイルの扱われ方" tabindex="-1">ファイルの扱われ方 <a class="header-anchor" href="#ファイルの扱われ方" aria-label="Permalink to &quot;ファイルの扱われ方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>動作</th><th>影響</th></tr></thead><tbody><tr><td>指定したフォルダから直接読み込みます。</td><td>取り込みも複製もしません。編集は <code>data/</code> にだけ書き込まれます。改名・分割は前処理ダイアログで操作したときだけ実行されます。</td></tr><tr><td>ページは<strong>並び順</strong>で対応づけます。ファイル名ではありません。</td><td>改名すると順番が変わります。途中に 1 枚挿すと、以降のページがすべてずれます。</td></tr><tr><td>並びは自然順です。連続する数字は数値として比較します。</td><td>ゼロ埋めがなくても <code>2.jpg</code> は <code>10.jpg</code> より前に来ます。</td></tr><tr><td>WebP は表示できますが、コマ検出用にはデコードしません。</td><td><strong>自動分割</strong>を使うなら JPEG か PNG に変換してください。前処理の分割も PNG / JPEG のみ対応です。</td></tr><tr><td>1 枚の画像が 1 ページです。</td><td>見開きは 1 ファイルのままにするか、前処理で全言語を同時に分割してください。</td></tr></tbody></table><figure class="shot"><img src="'+o+'" alt="整理後のライブラリサイドバー。巻、話、言語バッジが並んでいる"><figcaption>整理済みの巻。言語ごとに 1 フォルダ、話ごとに 1 フォルダ、ページ数がそろっているので言語バッジも一致します。</figcaption></figure><h2 id="整理のチェックリスト" tabindex="-1">整理のチェックリスト <a class="header-anchor" href="#整理のチェックリスト" aria-label="Permalink to &quot;整理のチェックリスト&quot;">​</a></h2><p>原本を残したいなら、コピーのほうで作業してください。どのツールを使うかより、次の順番のほうが重要です。</p><ol><li><strong>回転と傾き補正。</strong> 読み方向はページごとに保存されますが、横倒しのスキャンを比較リーディングで直すことはできません。</li><li><strong>スキャナの黒枠と見開きの影を切る。</strong> ページ端がまっすぐだと、端に接するコマも検出されやすくなります。</li><li><strong>自動分割を使うなら WebP を JPEG / PNG に変換。</strong> セリフが読める画質は保ってください。</li><li><strong>1 話 1 フォルダ。</strong> 1 つのディレクトリに 2 話を混ぜないでください。話はコマテンプレート、位置合わせプリセット、エクスポートの単位です。</li><li><strong>本文でない画像を除く。</strong> 表紙、奥付、カラーページ、他の版に存在しない特典画像などです。これらは以降のページをすべてずらします。</li><li><strong>見開きは分割しないか、全版を同じ位置で分割する。</strong> 見開きは 1 ページとして数えます。日本語版だけ分割して中国語版を分割しないと、日本語の 12 ページ目が中国語の 12–13 ページ目になり、対応が崩れます。前処理の**分割…**なら全言語を一度に切れます。</li><li><strong>ファイル名は必要なら整える。</strong> ゼロ埋め（<code>001.jpg</code>）は差分確認や目視に便利ですが、スキャナは並び順と自然順を見るので <code>1.jpg</code> でも <code>001.jpg</code> でも動きます。前処理の<strong>ファイル名を変更</strong>は話全体を振り直し、保存済みのページデータも一緒に移します。</li></ol><h2 id="komayomi-内での改名と分割" tabindex="-1">KomaYomi 内での改名と分割 <a class="header-anchor" href="#komayomi-内での改名と分割" aria-label="Permalink to &quot;KomaYomi 内での改名と分割&quot;">​</a></h2><p><strong>前処理…</strong> を開き、巻を選びます。巻・話の表示名、ページ順、除外、ページの役割に加えて、各話のセクションに<strong>ディスク上のファイル</strong>があり、実際のファイル操作が 2 つ用意されています。画像形式の変換は引き続きアプリの対象外です。</p><p><strong>一括改名。</strong> 接頭辞、開始番号、桁数を入れて<strong>ファイル名を変更</strong>を押します。ボタンの上に表示されているページ順（矢印で並べ替えた順）で振り直し、ディスク上のファイルを実際に改名します（<code>001.jpg</code>、<code>002.jpg</code>…。拡張子はそのまま）。その話で全ページがそろっている言語はまとめて改名されるので、各言語の <em>n</em> ページ目は同じ絵のままです。ページが欠けている言語は変更せず、結果に一覧で表示します。</p><p>ページデータ、履歴、除外、ページの役割、保存済みのページ順はページ番号で管理されているため、同じトランザクションで移動し、参照を書き換えます。アプリ内の改名で注釈・メモ・コマ編集が孤立することはありません。改名後は巻を再読み込みするので、他の編集は先に適用してください（未保存の下書きは破棄されます）。</p><p>何かを動かす前に <code>data/file-ops/</code> へマニフェストを書き、変更前と変更後の名前をすべて記録します。途中で失敗するとバッチ全体を元に戻し、マニフェストを <code>rolled-back</code> にしてフォルダを元の状態に戻します。既に別のファイルが使っている名前は上書きせず、エラーで拒否します。</p><p><strong>ページを分割。</strong> ページの下の<strong>分割…<strong>を押し、見開きなら</strong>左右</strong>、それ以外は<strong>上下</strong>を選び、分割位置をパーセントで指定して確定します。画像は <code>&lt;名前&gt;-a</code> と <code>&lt;名前&gt;-b</code> に切られ、後半が次のページになり、以降のページが 1 つずつずれます。そのページを持つすべての言語を同じ位置で切るので、対応は崩れません。分割は実際の PNG / JPEG のみ対応し、WebP・GIF・BMP は拒否します。元画像は削除前に <code>data/file-ops/</code> へコピーされます。</p><p>元のページ文書は両方の半分に切り分けられます。半分に掛かるコマと注釈はその半分に残して座標を再計算し、コマ単位のメモはコマに追従、ページ単位のメモは前半に残ります。両方の半分は元ページの読み方向を引き継ぎます。分割後は、特にコマを横切った場合に両ページを確認してください。</p><div class="warning custom-block"><p class="custom-block-title">改名と分割はダイアログから取り消せません</p><p><strong>前回の適用を復元</strong>は <code>library.json</code> だけを戻します。改名と分割は UI では一方向です。元の名前や画像が必要なときは <code>data/file-ops/</code> のマニフェストとバックアップを使ってください。アプリ外での改名は引き続き安全ではありません。ページデータはページ番号で管理されるため、ファイルマネージャーやシェルでの改名では注釈が移動しません。</p></div><h2 id="注釈を始める前の確認" tabindex="-1">注釈を始める前の確認 <a class="header-anchor" href="#注釈を始める前の確認" aria-label="Permalink to &quot;注釈を始める前の確認&quot;">​</a></h2><ol><li>巻を追加し、サイドバーで開きます。</li><li>巻と話の行に出る警告を読みます。<em>言語間でページ数が違う</em> と <em>ファイル名がページ順と一致しない</em> は、整理ミスのサインです。</li><li>フォルダ構成が特殊なら、<strong>フォルダ検出の規則…</strong> を開き、プレビューで確認してから保存します。<a href="/KomaYomi-docs/ja/guide/folder-rules">フォルダ検出の規則</a>を参照してください。</li><li>最初、中央、最後のページを開き、同じコマに同じ絵が入っているか確かめます。ずれていれば、ページ数か見開きの扱いが間違っています。</li><li>ここまで確認してから<strong>自動分割</strong>を実行し、ノートを書き始めます。</li></ol><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>1 つの言語だけ 1 ページ多い。</strong> 表紙や奥付が余分なことが多いです。削除するか、他の言語にも同じページを足してください。</li><li><strong>見開きが 1 版だけ分割されている。</strong> 見開きはそのままにするか、全版を同じ位置で分割します。</li><li><strong>WebP ページの自動分割がめちゃくちゃになる。</strong> 形式を変換してください。検出は WebP をデコードしません。</li><li><strong>アプリ外で改名したらノートが次のページに移った。</strong> ページデータは番号で管理され、ファイルマネージャーやシェルの改名では移動しません。前処理の<strong>ファイル名を変更</strong>を使うか、注釈の前に改名してください。</li><li><strong>分割位置がコマを横切った。</strong> コマとコマの間を指定するか、分割後に両方の半分のコマを直してください。ページ単位のメモは仕様どおり前半に残ります。</li><li><strong>ページは正常なのにサムネイルの形式が混在する。</strong> サムネイルは拡張子ではなく中身に従います。実体が JPEG の <code>.png</code> も正しく表示されるので、見た目だけの問題です。</li><li><strong>注釈のあとでフォルダを組み替えた。</strong> 検出 ID が変わり、以前のページデータが見つかりません。フォルダ検出の規則は注釈の前に適用してください。</li></ul><h2 id="不足しているスクリーンショット" tabindex="-1">不足しているスクリーンショット <a class="header-anchor" href="#不足しているスクリーンショット" aria-label="Permalink to &quot;不足しているスクリーンショット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>図</th><th>用途</th></tr></thead><tbody><tr><td>改名の前後比較</td><td>ゼロ埋め・自然順と<strong>ディスク上のファイル</strong>欄の説明</td></tr><tr><td>分割フォーム</td><td>見開きの方向と分割位置</td></tr><tr><td>見開きの扱い</td><td>1 ページのまま残す場合と分割する場合の比較</td></tr><tr><td>ライブラリの警告表示</td><td>確認に使う 3 種類の警告</td></tr></tbody></table><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a> — フォルダ構成、言語の別名、巻の設定。</li><li><a href="/KomaYomi-docs/ja/guide/folder-rules">フォルダ検出の規則</a> — 特殊なディレクトリ構成への対応。</li><li><a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a> — 最初のページを開いたあとにすること。</li><li><a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> — ページデータの管理方法とバージョン。</li><li><a href="/KomaYomi-docs/ja/terminology">用語集</a> — コマ・ページ・注釈の共通語彙。</li></ul>',26)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
